    ['**1**', '**認知症施策推進計画を一体で策定する**', '**認知症基本法（令和5年法律第65号）第13条第1項。** 第9期は基本方針3として2施策を置いていたが、本計画では第6章の基本方針3を3施策に拡充し、計画名にも掲げる。**あわせて基本方針3の冒頭に(0)「認知症施策推進計画としての位置づけ」を置き、同法の基本的施策8項目（第14条〜第21条）との対応、認知症の人およびご家族の参画、実施状況の評価と公表を明記する。第9期にはいずれも記載がない**'],
    ['**2**', '**第9章に成果指標の一覧表と、施策との対応表を新設する**', '**第9期は8指標が第5章の各施策に分散し、一覧がなかった。** 結果として実績の確認が計画の最終年度までずれ込み、1指標は目標と実績が別のものを指していた。**本計画では43項目の一覧に加え、第6章の20施策のどれがどの指標で測られるかの対応表を置く。突き合わせた結果、7施策に指標がないことが分かり、うち重点課題に直結する3施策に指標を新たに置いた（9-3）**'],
    ['**3**', '**第9章に評価の主体・時期・様式・公表方法を明記する**', '**第9期の第7章は1頁2項目で、誰がいつ何をするかの記載がなかった**'],
