    ['**5**', '**一般介護予防事業評価事業を事業として位置づける**', '**厚生労働省調査（令和6年度）で「実施無」。** 評価を行う事業がないことが、成果指標の実績が集まらない根本原因である'],
    ['**6**', '**将来推計に令和15年度・令和30年度を加える**', '**仕様書3(3)c。** 第9期は令和22年度までであった'],
