    ['**8**', '**「通いの場」と「オレンジカフェ」を別の指標に分ける**', '**第9期の「通いの場創出事業（オレンジカフェ事業）の実施か所数41→71か所」はオレンジカフェの箇所数である。** 国の調査でいう通いの場は令和6年度13か所であり、別のものを指していた'],
    ['**9**', '**人口推計を社人研推計に統一する**', '**第9期は町のコーホート変化率法（直近3か年の平均変化率）。** 20年超の外挿には向かない《要確定1》'],
    ['**10**', '**章立てを全9章＋資料編に組み替え、第4章（住民ニーズと地域課題）と第7章（中長期を見据えたサービス提供体制の確保）を新設する**', '**国の第10期基本指針（案）は2040年度を含む中長期推計を必須化し、これに対応する章を求めている。** 第9期には対応する章がない。あわせて、アンケート調査の結果を独立した章に置き、統計から得た事実と住民の意向を対にして課題整理につなぐ'],
