H1('第１章　計画策定にあたって')
H2('１　計画策定の趣旨と背景')
P('介護保険制度は平成12年4月の施行から27年が経過し、高齢者の生活を支える制度として定着している。本町においては、早期から介護予防・自立支援重度化防止に取り組み、**第7期計画において岩手県内で唯一の介護保険料の引下げを実現した**（第3章4）。')
P('一方、本計画期間である令和9年度から令和11年度は、**団塊の世代がすべて85歳以上となる令和14年（2032年）を目前に控える期間**にあたる。**本町では、認定者数の総数が横ばいであるにもかかわらず、要介護1から要介護2への移行が急速に進んでいる**（第2章4）。数の増加ではなく状態の変化に対応する期となる。')
P('本計画は、こうした状況を踏まえ、高齢者福祉計画・介護保険事業計画・認知症施策推進計画の3つを一体のものとして策定する。')
H2('２　計画の位置づけ')
TBL([
    ['**計画**', '**根拠法**', '**内容**'],
    ['**高齢者福祉計画**', '老人福祉法第20条の8', '老人福祉事業の供給体制の確保に関する計画'],
    ['**介護保険事業計画**', '介護保険法第117条', '**介護給付等対象サービスの見込量、地域支援事業の量の見込み、介護給付適正化に関する事項**ほか'],
    ['**認知症施策推進計画**', '共生社会の実現を推進するための認知症基本法第13条第1項', '**市町村認知症施策推進計画。** 本計画では第6章 基本方針3をもってこれに充てる'],
], widths=[3.6, 4.4, 9.0])
P('本計画は、第十一次金ケ崎町総合計画を上位計画とし、金ケ崎町地域福祉計画、金ケ崎町健幸増進計画（第3次）、岩手県高齢者福祉計画・介護保険事業支援計画（いわていきいきプラン）、奥州金ケ崎地域医療介護計画と整合を図る。')
P('**なお、第十二次金ケ崎町総合計画が策定中である。**本計画の基本理念は、第8期・第9期の方向性を継承しつつ、**第十二次金ケ崎町総合計画を踏まえて文言を調整する。**同総合計画の策定の状況により、**５-２の基本理念の文言が変わり得る。**')
P('**認知症基本法第13条第2項は、市町村認知症施策推進計画について「市町村地域福祉計画、市町村老人福祉計画、市町村介護保険事業計画その他の法令の規定による計画であって認知症施策に関連する事項を定めるものと調和が保たれたものでなければならない」と定めている。本計画は、高齢者福祉計画（老人福祉法第20条の8）および介護保険事業計画（介護保険法第117条）と一体で策定するものであり、これが調和を保つ最も確実な方法である。** 地域福祉計画との調和は、第5章2の基本理念および第6章 基本方針4（地域共生社会）において図る。')
P('**なお、認知症基本法第13条第1項は、市町村計画を「国の認知症施策推進基本計画（都道府県計画が策定されているときは、基本計画及び都道府県計画）を基本とするとともに、当該市町村の実情に即したもの」とすることを求めている。** 本計画は、国の認知症施策推進基本計画（令和6年12月3日閣議決定）および岩手県の計画を基本としつつ、第2章3・第4章6で把握した本町の実情に即して策定する。')
H3('金ケ崎町都市計画マスタープランとの整合')
P('**金ケ崎町都市計画マスタープラン（計画初年度 令和3年度／目標年次 令和22年度）は、都市像を「健幸田園都市（Wellness Garden City）金ケ崎」とし、5つの基本方針の第一に「6つの生活圏の住み慣れた地域で、安心して住み続けられる日常に必要な都市機能の形成（誘導・創出・維持管理）」を掲げている。**')
P('**これは介護保険法第5条第3項の「可能な限り、住み慣れた地域でその有する能力に応じ自立した日常生活を営むことができるよう」と同じ思想であり、本計画の基本理念（第5章2）はこれと軌を一にする。**')
P('**同計画書が掲げる「まちづくりにおける課題」21項目のうち、次の4項目は本計画と共通の課題であり、いずれも6生活圏すべての「地区の主要な課題」に掲げられている。**')
