BUL('**介護人材実態調査**（令和8年8月24日集計。**26事業所に依頼、18事業所回収・回収率69.2％**。職員個票260人分）')
P('**本計画では、認知症施策推進計画を含むことから、認知症の人およびその家族等の意見を聴く機会を設ける。** 認知症基本法**第13条第3項において準用する同法第12条第3項**は、市町村計画の案を作成しようとするときは、あらかじめ、認知症の人および家族等の意見を聴くよう努めなければならないと定めている。**第9期にはこの手続の記載がない。方法は第6章 基本方針3(0)に掲げる。**')
H2('５　日常生活圏域')
P('本町は第7期計画より日常生活圏域を1圏域としている。**本計画においてもこれを維持する。** 町全体で住民の生活を支える基盤づくりを推進することが有意であるとの判断による。')
P('**ただし、圏域ごとのサービス整備の状況を記載することが国の基本指針で求められているため、1圏域を維持する理由と、町内6生活圏（地区生涯教育センター単位）での資源の分布を第2章に示す。**')
H3('6生活圏の定義')
P('**本計画で「6生活圏」というのは、地区生涯教育センターの圏域である。金ケ崎町都市計画マスタープラン第4章1は「地区区分は、地区生涯教育センターを中心とする生活圏を単位として、都市計画区域内を6地区に区分し、設定しました」とし、6地区を街・三ケ尻・南方・西部・永岡・北部としている。**')
P('**その由来は、昭和54年に全国に先駆けて宣言した「生涯教育の町」である。同計画書は「生涯教育及び地域づくりの活動拠点として町内6つの生活圏（街地区、三ケ尻地区、南方地区、西部地区、永岡地区、北部地区）に、公民館・体育館・グラウンドを有する地区生涯教育センターを配置し、『ひとづくり・地域づくり・まちづくり』の活動を進めています」としている。**')
