P('**1圏域を維持する理由は、①町の人口が15,085人であり圏域を分けると各圏域の被保険者数が統計上の意味を持たない規模になること、②施設・居住系サービスがいずれも町内1〜2か所であり圏域単位の整備目標を立てられないことによる。**')
P('**一方、6生活圏には地区生涯教育センターがあり、都市計画マスタープランはこれを「地域拠点＝生活圏の中心となるエリア」と位置づけている。公民館・体育館・グラウンドを備えた施設が6圏域すべてにあるため、通いの場・一般介護予防事業・生活支援体制整備の協議体は、この6圏域を単位として展開する（第6章 基本方針1・2）。**')
