FIG('out/fig/s1_jinko.png', '人口の推移と将来推計　―　総人口は減り、高齢化率は上がる', width=14.8, src='資料：上表に同じ。**高齢化率は31.7％から32.9％へ1.2ポイント上がる。上がり方はゆるやかである。**')
FIG('out/fig/s2_uchiwake.png', '高齢者人口の内訳の変化　―　変わるのは総数ではなく中身である', width=14.6, src='資料：上表に同じ。**65〜74歳が187人減り、75〜84歳が218人増える。85歳以上は計画期間中は52人減る。**')
P('**高齢者数は6年間で21人減るにとどまり、ほぼ横ばいである。変わるのは内訳である。** 75歳以上が2,633人から2,799人へ166人増え、高齢者に占める割合は55.2％から59.0％へ3.8ポイント上がる。**「高齢者が増えるから需要が増える」のではなく、「高齢者の中身が入れ替わるから需要が増える」局面にある。**')
P('**世帯の状況　《要回答》** 3世代世帯等の減少（▲716世帯）と女性就業率の上昇（55〜59歳 72.3％→80.0％）は把握しているが、**計画掲載用の最新の世帯類型別数値を町から受領する。**')
H3('【留意】上位計画の人口と本計画の推計人口は一致しない')
P('**第十一次金ケ崎町総合計画は令和12年の目標人口を15,075人とし、金ケ崎町都市計画マスタープランは目標年次（令和22年度）までの計画期間中に15,000人程度を見据えたまちづくりを設計するとしている。本計画の推計人口はこれを下回る。**')
