SRC('資料：金ケ崎町都市計画マスタープランp13（①は第十一次金ケ崎町総合計画 第三章人口ビジョン「将来人口のケース別推計結果 パターン④」）。**本計画の推計は社人研 令和5年推計（自然体推計の計算過程確認シート）による第3の系列であり、①②のいずれとも異なる**')
P('**住民基本台帳（令和7年3月31日）の実績は総人口15,085人・65歳以上4,662人・高齢化率30.9％である。町独自推計の令和7年（15,294人・4,833人・31.6％）より総人口で209人、高齢者で171人少ない。**')
P('**この違いは誤りではなく、推計の目的の違いである。総合計画の目標人口は出生率の向上と転入増・転出抑制の施策効果を織り込んだ政策目標であり、介護保険事業計画の推計人口は保険料算定の基礎となる自然体推計である。政策目標を保険料算定に用いると給付費が過小に見積もられ、財政安定化基金からの借入や次期の急激な保険料上昇を招く。**')
P('**本計画では、推計人口は社人研 令和5年推計に統一し、総合計画の目標人口とは別の系列であることを本文に明記する《要確定1》。**')
H3('行政区別の高齢化率　―　15.3％から60.0％まで4倍の開きがある')
P('**アンケート調査結果報告書の資料編に、47行政区の人口・65歳以上高齢者数・高齢化率の表がある。合計は15,085人・4,662人・30.9％で、住民基本台帳（令和7年3月31日）と完全に一致する。**')
