FIG('out/fig/s3_gyoseiku.png', '行政区の数と高齢者の数は一致しない', width=13.6, src='資料：上表に同じ。**高齢化率40％以上の25区は行政区の53.2％を占めるが、そこに住む高齢者は42.2％である。高齢化率が高い区ほど人口が小さい。**')
P('**町全体の高齢化率は30.9％であるが、行政区の間では谷地下の15.3％から長志田の60.0％まで4倍の開きがある。高齢化率が40％を超える25区に、町の高齢者の42.2％が住む。**')
P('**ただし「高齢化率が高い地区」と「高齢者が多い地区」は別である。** 高齢化率が50％を超える4区（長志田・町下・野崎・町上）はいずれも人口95〜145人と小さく、4区合わせても高齢者は256人にとどまる。**一方、高齢者数が最も多いのは清水端の237人（高齢化率32.1％）、次いで谷地下の212人（同15.3％・町内最大の人口1,386人）である。**')
P('**したがって、サービスの需要は高齢者数の多い行政区に集まり、見守り・移動支援・通いの場の担い手の確保は高齢化率が高く人口の小さい行政区で難しくなる。** 長志田では145人中87人が高齢者であり、支え手そのものが地区内にいない。')
P('**なお、6生活圏と行政区の対応表は、アンケート調査結果報告書にも都市計画マスタープランにもない。** 行政区名と人口メッシュの字名を照合しても47区中14区しか一致せず（行政区は自治会の単位、メッシュの住所は地番区域）、**町から「6生活圏ごとの行政区一覧」を受領する必要がある**《要回答24》。これが得られれば、上記の行政区別データから6生活圏別の高齢者数・高齢化率の実測値が算出できる。')
H3('【留意】85歳以上人口は、実績では増えているが、計画期間の推計では減る')
P('**85歳以上人口は本計画の主要指標に位置づける（第5章3　重点課題1）。ただし、実績の系列と推計の系列で動きの向きが異なるため、両者を混ぜて記載してはならない。**')
