P('**実績では85歳以上が年25人のペースで増えている**（令和6年度末1,001人→令和7年度末1,026人）。**一方、社人研推計では計画期間中はむしろ減り、令和11年度に1,010人となる。**')
P('**これは大正末〜昭和初期生まれの世代が90歳を超えて減っていく時期と、団塊の世代が85歳に達する前の谷が重なるためである。85歳以上が本格的に増えるのは令和17年度（1,101人）以降であり、令和22年度に1,257人となる**（第2章7(2)）。')
