P('**したがって、本計画で「85歳以上人口の増加への備え」を掲げる場合、それは計画期間の3年間に増えるからではなく、令和17年度以降の急増に対して今から備える必要があるからである。** 計画期間中の実数は減るため、**85歳以上人口そのものを3年間の目標指標に用いることはできない。指標は85歳以上の認定率・重度化率など、人数によらない比率で置く（第9章3）。**')
P('**なお、第1回策定委員会資料の推計表では85歳以上を令和7年度1,023人→令和11年度1,039人→令和30年度1,322人と増加する系列で示しているが、これは社人研推計（1,074人→1,010人→1,242人）と一致しない。本素案は社人研推計に統一している《要確定1》。**')
H3('【留意】高齢者の住む場所が町内で移動する')
