FIG('out/fig/s5_ninchi_jiritsu.png', '認知症高齢者の自立度別の増減（令和2年4月末→令和6年10月末）', width=13.6, src='資料：上表に同じ。**Ⅱ以上の増加93人はすべてⅡbで生じており、Ⅲ以上は9人しか増えていない。Ⅱaはむしろ9人減っている。**')
P('**【留意】認知症高齢者等の割合には、もう1つの系列がある。** 現状分析レポートは、認知症高齢者等の日常生活自立度調査（岩手県）により**令和5年度の割合61.8％**を用い、令和7年度を約488人としている。**本表のＢ7による69.3％を用いると565人となり、77人の差が生じる**（0-6⑥）。**自立度別の内訳（Ⅱa・Ⅱb・Ⅲ以上）はＢ7にしか存在しないため、本節の分析（増加はすべてⅡbで生じている）はＢ7による。ただし人数の水準については、いずれの系列を計画の基礎とするかを確定する**《要回答51》**。**')
P('**自立度Ⅱ以上の認知症高齢者は4年半で93人増えた。しかし増加分の93人はすべてⅡbで生じており、Ⅲ以上は9人（2.6％）しか増えていない。Ⅱaはむしろ9人減っている。**')
P('**Ⅱbは「家庭内でも日常生活に支障を来すような症状・行動や意思疎通の困難さがみられるが、誰かが注意していれば自立できる」状態である。必要なのは施設の量ではなく、注意を向ける人と場である。** この事実は、住民が認知症について必要と考えるものの上位4つが「正しい理解70.7％・話し相手58.6％・見守り56.5％・声かけ55.5％」といずれも住民の関わりであり、「適切な介護サービス55.1％」がその次に来るという調査結果（第4章6）と一致する。')
P('**また、認定者に占めるⅡ以上の割合は69.3％で4年半前と同じである。認知症高齢者が増えているのは、認知症になりやすくなったからではなく、認定者数そのものが増えたためである。** 第10期の認定者数はほぼ横ばいであり（第8章2）、認知症高齢者数も横ばいで推移する見込みである（第8章4-3）。')
