P('**悪化しているのは要介護1だけである。** 全体の重度化率は同じ期間に24.2％から31.1％へ6.9ポイント上がったにとどまる。**要介護2の重度化率は令和7年度25.0％と最も低く、要介護1から入ってきた人が要介護2に滞留する形になっている。**')
P('**入口ではむしろ軽く判定されている。** 要支援2／要介護1の振り分けで要介護1となる割合は71.1％（令和2年度）から62.9％（令和7年度）へ下がっている。**それでも要介護2が増えるということは、増加の原因が新規認定ではなく更新時の重度化にあることを示す。**')
P('**要介護1と判定された人の状態像は、7年間一貫して「認知機能の低下」が75〜84％を占める**（残りは「不安定な状態」）。**要介護1から要介護2への移行の背景に認知機能の低下があり、認知症施策と介護予防を一体で設計する根拠となる（第5章3　重点課題1・5）。**')
P('**この事実は外部評価とも整合する。** 交付金の成果指標群（目標Ⅳ。2つの交付金に共通）の「長期的な要介護度の変化（要介護1・2）」は3年連続で0点である（第3章5）。')
