FIG('out/fig/s6_kyufu.png', 'サービス区分別の給付費の増減（令和6年度→令和7年度）', width=14.2, src='資料：上表に同じ。**給付費の増加52,615千円のうち44,128千円（83.9％）は居宅サービスの増加分である。**')
SRC('※　月報の様式は令和7年5月審査分から変わり、それまで「居宅（介護予防）サービス」の内数であった居宅介護支援・介護予防支援が別掲となった。**上表の令和6年度は令和7年度と揃えるため、居宅サービスから居宅介護支援等59,308千円を除いて計上している。** また上表の給付費はサービス費であり、高額介護サービス費・特定入所者介護サービス費等を含む標準給付費（令和6年度1,262,380千円）とは範囲が異なる')
