P('**居宅の増加は、受給件数の増加が主で、1件あたりの利用量の増加がこれに加わる。** 月平均の受給件数は872件から933件へ**＋7.0％**、1件あたり給付費は39.6千円から41.0千円へ**＋3.4％**であり、両者の積が＋10.6％となる。**したがって見込量は、まず対象者数の推計で置き、単価の上昇は別の要素として扱う（第8章3・4）。**')
