SRC('※　**計画値は実利用者数（人／月）、実績は受給件数（件／月）であり、単位が異なる。** 施設サービスと居宅介護支援等は1人1件であるため対比の精度が高いが、区分の合計（居宅サービス・地域密着型サービス）は1人が複数のサービスを使えば重複して数えられる。**別表1では実利用者数に揃える。**')
P('**居宅介護支援・介護予防支援が計画比119.3％である点は重い。** ケアマネジメントの対象者が計画より約67人／月多い一方で、**居宅介護支援専門員は14人→13人→12人と減っている**（第9期計画書 p53）。**第10期の見込量は、需要側だけでなく支援専門員の確保を前提条件として置く（第6章 基本方針4）。**')
P('**地域密着型サービスが計画比91.6％である点は、需要が小さいのか提供体制の制約かを事業所ヒアリングで確認する（第9章 確認事項）。**')
P('**サービス種類別の計画値・実績対比表は別表1に置く。** 第9期の計画値は第9期計画書 第6章3・4の推計表から、実績は介護保険事業状況報告の月報から取る。**単位は「利用者数＝人／月」「給付費＝千円／年」に統一する（第9期は章により単位が異なっていた）。**')
