P('**本町の高齢者人口は単調に減らない。** 第1号被保険者数は令和17年度に底（4,659人）を打ち、令和27年度に山（4,823人）を迎える。**団塊ジュニア世代が65歳に到達する時期にあたり、65〜69歳が令和17年度873人から令和22年度1,071人へ198人増えるためである。**')
P('**75歳以上人口は二つのこぶを持つ。** 令和17〜22年度に第1のこぶ（2,871〜2,875人）、令和27年度に谷（2,792人）、**令和32年度に第2のこぶ（2,883人）が来る。令和30年度は第2のこぶの立ち上がりの上にある。**')
P('**したがって「令和22年度（2040年）にピークが来て、以降は減少する」という説明は本町には当てはまらない。** 「令和17年度以降、高い水準で推移し、令和32年度に再び上向く」と記載する。**施設の整備・用途転換の判断は、この形を前提に行う。**')
P('**なお第9期計画は「後期高齢者の人口は令和12年度まで増加し、以降は減少に転じる」としていたが、これは町独自のコーホート変化率法によるものであり、社人研推計では令和22年度まで増加する。本計画では推計の基礎を社人研推計に改める。** その差は令和22年度の高齢者人口で443人（10.2％）にのぼる。')
