FIG('out/fig/s9_hokenryo.png', '介護保険料基準額の見通し（低位・中位・高位）', width=13.6, src='資料：上表に同じ。**令和30年度の幅3,980円は、第1号被保険者負担割合と1人あたり給付費の置き方による。単一値では示せない。**')
P('**第10期の中位5,322円は、第9期の取崩前5,450円に対し▲128円（▲2.3％）である。準備基金を第9期と同額取り崩せば4,782円となり、第9期の4,900円に対し▲118円（▲2.4％）となる。** 令和9〜11年度は85歳以上が減り認定者数も横ばいであるためで（第7章1）、施策を縮小した結果ではない。')
P('**令和15年度は中位の単一値で示す。令和30年度は幅で示す**《要確定2》**。** 令和30年度は第9期から22年先であり、1人あたり給付費の年率0.5％の置き方の違いが11.6％の差になる。**単一値を示すことは確度を偽ることになる。**')
P('**令和30年度の中位7,500円のうち約1,250円は、第1号被保険者負担割合が23％から28％へ上がるとの仮定によるものである。** 第1号被保険者負担割合は、全国の第1号・第2号被保険者の人口比に応じて3年の計画期間ごとに政令で定められるものであり、**本町の給付水準とも政策判断とも関係がない。この分を分けて示す。**')
P('**ただし、令和12年度以降の24〜28％は国の推計ツールが長期推計用に置いている仮定値であって、政令で定められた値ではない。** 第10期ワークシートの係数シートに掲げられた令和12年度以降の値は、第9期のワークシートの値と1桁も違わない。資料には「国の推計ツールの仮定による」と明記する。')
P('**第1回策定委員会資料に掲げた参考試算との関係を、あらかじめ整理しておく必要がある。**')
