SRC('自然体推計の保険料基準額は見える化システムの計算過程確認シートによる（令和12年度6,497円・令和17年度7,090円・令和22年度7,104円・令和27年度7,352円・令和32年度7,593円）。令和15年度・令和30年度は前後の年度から補間した。第1号被保険者負担割合は令和12年度24％・令和17年度25％・令和22年度26％・令和27年度27％・令和32年度28％。**同シートの令和8年度の認定者数は令和7年度の値のまま入っているため、長期の値は2.4％程度高めに出ている（第8章1）。長期推計は参考値として扱い、確定した基準年度で組み直す**')
P('**委員会資料の参考試算は、給付費の伸びを補正後被保険者数の伸びで除した簡便な試算であり、第1号被保険者負担割合が23％のまま据え置かれることを前提としている。令和22年度・令和30年度では自然体推計を23％に引き直した値とおおむね一致する。**')
P('**したがって、第3回（12月）に国の推計ツールによる正式な算定をお示しすると、第1回で示した水準より令和22年度で約800円、令和30年度で約1,250円高くなる。委員会において「なぜ上がったのか」という疑義を生じさせないため、第1回の資料の段階で「第1号被保険者負担割合の上昇は含まない」旨を明記しておくことを提案する。**')
