SRC('資料：見える化Ｄ49（地域差指数・令和5年）。全国を1.00とした指数。**金ケ崎町の値のみを掲げており、他の市町村の個別のデータは扱っていない**')
FIG('out/fig/s11_chiiki.png', '全国との地域差（地域差指数・令和5年）', width=14.2, src='資料：上表に同じ。**金ケ崎町の値のみを掲げており、他の市町村の個別のデータは扱っていない。**')
P('**年齢構成をそろえてもなお、本町の認定率は全国の0.80倍である。** 岩手県（0.95）と比べても低い。**「認定率が低いのは高齢化率が低いからだ」という説明は、この指標により否定される。人口構造をそろえても2割低い。**')
P('**一方、第1号被保険者1人あたりの給付月額は0.97と全国並みである。** 認定率が2割低いにもかかわらず給付水準が全国並みであることは、**認定を受けた人に対しては相応のサービスが提供されていることを示す。**')
P('**第9期の目標「認定率16.2％」は、全国で最も低い部類の水準から、さらに引き下げることを求めるものであった。** 目標の設定そのものに無理があったと考えられる。**第10期では、水準の低さを維持することではなく、重度化の防止（調整済み重度認定率）と軽度の増加の抑制（調整済み軽度認定率）を分けて目標に置く。**')
H2('３-２　サービス種類別の計画値・実績対比')
P('**サービス種類別の計画値・実績対比表は別表1に置く。作成済である。**　計画値は第9期計画書 p76〜p78（利用者数）・p79〜p80（給付費）から、実績は介護保険事業状況報告 様式2の月報25か月分から取った。**令和6年度の給付費の総計は1,185,811,534円で、年報の総計と1円まで一致する。**')
P('**主な結果は次のとおりである。**')
BUL('**計画を大きく上回ったサービス**　定期巡回・随時対応型訪問介護看護（給付費で令和7年度967.4％）、居宅療養管理指導（利用者数138.4％）、福祉用具貸与（131.6％）、短期入所生活介護（130.4％）、訪問介護（124.6％）、居宅介護支援（125.9％）。**いずれも在宅生活を支えるサービスである。**')
BUL('**計画を大きく下回ったサービス**　地域密着型通所介護（利用者数40.0％）、短期入所療養介護（64.6％）、訪問入浴介護（68.8％）、小規模多機能型居宅介護（給付費83.0％）、認知症対応型共同生活介護（87.4％）。')
BUL('**施設サービスは計画111人／月に対し実績111.3件／月で計画どおりであるが、内訳が入れ替わっている。** 介護老人福祉施設が90.5％、介護老人保健施設が110.2％である（令和7年度）。')
BUL('**予防給付費は令和6年度86.0％・令和7年度68.5％と大きく計画を下回っている。** 一方で総合事業費は計画どおり執行されている（3-3）。**要支援者が予防給付と総合事業のいずれで支えられているかを確認する**《要回答18》。')
BUL('**計画値が0でありながら実績のあるサービスがある。** 住宅改修（0.8件／月）、特定施設入居者生活介護（1.0件／月）。**第10期では実績のあるサービスを0で置かない。**')
P('**令和8年度の実績が確定した時点で3か年の対比に更新する。**')
P('**なお第9期計画書の68表は第8期（令和3〜5年度）の計画値・実績対比であって、第9期の計画値ではない。** 第9期の計画値は同計画書の第6章3・4にあり、別の場所・別の様式・別の単位に置かれていた。**本計画では前期の対比表と当期の推計表を同一の様式・単位で並べる。**')
H2('３-３　地域支援事業の実施状況')
P('**第9期計画は第3章2に「地域支援事業の実施状況」を置いていた。本計画でもこれを継承する。** 介護保険法第117条第3項は地域支援事業の量の見込みを計画に定めることを求めており、**その実績を評価しなければ次期の量を置けない。**')
H3('（1）事業費')
TBL([
    ['**区分**', '**計画（令和6年度）**', '**実績（令和6年度）**', '**計画比**'],
    ['**介護予防・日常生活支援総合事業費**', '45,104千円', '**45,264千円**', '**100.4％**'],
    ['**包括的支援事業・任意事業費**', '20,106千円', '**19,749千円**', '**98.2％**'],
    ['**計**', '**65,210千円**', '**65,013千円**', '**99.7％**'],
], widths=[5.0, 3.6, 3.6, 3.0])
SRC('**実績額は年報に直接は掲載されていない。経理状況の交付金決定額から逆算した。** 総合事業は国庫支出金9,053,200円÷20.0％＝45,266千円、支払基金交付金12,221,000円÷27.0％＝45,263千円の2経路で検算している。包括的支援事業・任意事業は国庫支出金7,603,365円÷38.5％＝19,749千円。**交付決定額に基づく額であり、決算額とは一致しない場合がある**（令和6年度には令和5年度分の返還922,409円が生じている）《要回答38》')
P('**事業費はおおむね計画どおりに執行されている。したがって、後述の未実施事業は「予算がつかなかった」ものではなく、「事業として組み立てられていない」ものである。** この区別は第10期の施策設計に直結する。')
