    ['', '生活支援体制整備事業', '**生活支援コーディネーターは1人（第1層）。生活支援サポーター養成研修の受講者は令和7年度までの累計109人で、第9期の目標84→104人を達成**'],
    ['', '認知症初期集中支援推進事業', '**1チーム。対象者数は**《要回答49》'],
    ['', '認知症地域支援・ケア向上事業', '**認知症地域支援推進員1人。交付金では配点12点中6点（全国平均6.0点）**'],
    ['', '認知症サポーター活動促進・地域づくり推進事業', '**サポーター累計3,946人（人口の26.2％・交付金は満点）。一方、ステップアップ講座修了者は0人（配点12点中0点）、チームオレンジは**《要回答49》'],
    ['', '地域ケア会議推進事業', '**開催回数・検討件数は**《要回答》'],
