P('**全国平均を大きく下回る2項目は、いずれも岩手県全体の傾向である。在宅医療・在宅介護連携は本町54点に対し県平均も54.0点でまったく同じであり、県平均が全国を14.3点下回っている。介護給付適正化も県平均52.0点が全国を17.2点下回り、本町はこれを4.0点上回る。** ただし**介護給付適正化は法定記載事項であり、県全体が低いことは本町が取り組まない理由にならない。**', before=6.0)
P('**本町が県平均を下回っている項目は、7つのうち「認知症総合支援」ただ1つである**（44点対49.3点・▲5.3点、**県内25位／33**）。**認知症施策推進計画を策定する期に、県内でも下位にある。これが本町固有の弱点である。** 一方、持続可能な地域（県内5位）と成果指標群（県内9位）は県内で明らかに上位である。')
P('**成果指標群は令和8年度に70点から55点へ15点低下した。全国平均は47.8点で3年間変わっておらず、低下は本町側の要因である**《要回答9》。')
