SRC('資料：保険者機能強化推進交付金・介護保険保険者努力支援交付金　全国一覧表（令和7年度・令和8年度）の枝ごとの得点を当方が突き合わせた')
P('**読み取れることは3つある。**', before=6.0)
BUL('**低下の29点のうち30点分は成果指標群である。**成果指標群は要介護度の変化と健康寿命の実績で決まり、計画の書きぶりでは動かない。**すなわち、令和8年度の低下は取組の後退によるものではない。**')
BUL('**要介護1・2について、短期（1年）は改善し、長期（3年）は悪化している。**これは第2章4の実測（要介護1の更新時に要介護2以上へ移る割合24.1％→57.0％）と同じ方向を指しており、**重点課題1（要介護1・2層の重度化防止）の根拠を補強する。**')
BUL('**認知症総合支援の▲3点は配点の改定によるものであり、取組の後退ではない。**ただし**新設されたカ（認知症施策推進計画の策定着手・5点）を本町は得ていない。**本計画の策定がその要件にあたる。')
H3('岩手県自身の取組　―　県の伴走支援を使える')
P('**交付金には都道府県分があり、都道府県による市町村支援の取組が評価される。岩手県は令和8年度562点／800点で全国12位（全国平均535.6点）、令和7年度は607点で全国2位である。**')
P('**とくに、都道府県分の目標Ⅰ（ⅰ）体制・取組指標群（配点60点）において岩手県は満点である**（全国平均53.4点）。**「研修事業・アドバイザー派遣等の具体的な取組を実施している」「個々の市町村の要望を踏まえ、伴走支援を実施している」「交付金の評価結果の改善に向け、情報共有・研修等の支援を実施している」のいずれも「実施している」と申告している。本町はこれを求められる立場にある。**')
P('**県にとっても利益がある。** 都道府県分の活動指標には「伴走支援の実施回数」（岩手県は8点中4点）と「管内市町村平均点」（同0点）があり、**本町への支援と本町の得点向上は、そのまま県の得点になる。第9章2の進捗管理に、県との協議を位置づける。**')
