SRC('資料：令和8年度 評価指標（市町村分）本文および全国一覧表。**「県内上位群」は岩手県内33保険者のうち合計得点が上位3分の1にあたる11保険者のうち、その枝で得点している数である。個別の保険者名および個別の得点は用いていない。**')
P('**県内上位群が揃って得点していながら本町が得点していない枝のうち、最も差が大きいのは在宅医療・在宅介護連携である。**支援 目標Ⅲ（ⅰ）の未得点32点は、そのすべてが県内上位群の過半が得点している枝である（体制・取組指標群の未得点156点のうち、上位群の過半が得点しているのは96点であり、その3分の1がこの1目標に集まっている）。**「連携が行われていない」のではなく、「行われている連携を町が把握し、記録し、計画に位置づける仕組みがない」ことによる（第7章3）。**', before=6.0)
P('**一方、活動指標群と成果指標群の未得点339点は、計画の書きぶりでは動かない。**このうち県内上位群の過半が得点しているのは57点にとどまり、残りは全国でも該当が少ない。**交付金を目標に置くのであれば、体制・取組指標群の146点（区分Ａ＋Ｂ）に絞るのが実際的である。**')
H3('成果指向型配分枠（配点100点）　―　本計画がそのまま申告材料になる')
P('**令和8年度から、上記800点とは別に「成果指向型配分枠」（配点100点・単一指標）が設けられている。「成果指向型の介護予防・健康づくりに関する取組を行っているか」を問うもので、①十分なデータに基づく地域分析　②年齢・状態・性別等による対象層の特定　③客観的に評価できるアウトプット指標　④効果検証できるアウトカム指標　⑤両指標への具体的な目標値の記載　の5つを求めている。**')
P('**この5つは本計画が既に満たしている。** ①は第2章〜第4章、②は重点課題1（要介護1・2層。更新時に要介護2以上へ移る割合が24.1％→57.0％）、③は第9章3の活動指標18項目、④は同 成果指標9項目、⑤は23項目に置いた目標値である。**追加の事業も調査も要しない。** ただし**同枠は全国一覧表に含まれておらず、本町の得点は不明である**《要回答8》。')
