SRC('資料：アンケート調査結果報告書。**該当率は回答者全体（n=474・無回答を含む）を分母とした報告書の公表値である。** 社会的役割の低下・知的能動性の低下・ＩＡＤＬの低下は、報告書が「やや低い」と「低い」を合わせて該当者とする旨を明記している。**「低い」のみを取ると、それぞれ29.7％・13.7％・3.8％となり、順位が変わる。**')
FIG('out/fig/s12_risk.png', '生活機能リスクの該当率', width=14.2, src='資料：上表に同じ。**判定基準の厳しさが項目ごとに異なるため、この順位を「本町で最も深刻なリスク」と読むことはできない。**')
P('**最も該当率が高いのは社会的役割の低下（55.6％）である。** 次いで認知機能の低下（44.1％）、うつ傾向（42.8％）が続き、いずれも回答者の4割を超える。')
P('**社会的役割の低下と閉じこもり傾向は、通いの場・社会参加の施策に直結する（第6章 基本方針1）。うつ傾向と認知機能の低下は、認知症施策および要介護1・2層の重度化防止に直結する（第6章 基本方針1(3)・基本方針3）。**')
P('**なお、判定基準が異なるため、上表の順位を「本町で最も深刻なリスク」と読むことはできない。** 施策の優先順位は、該当率ではなく、次項の複合リスクの重複と、統計から得た事実（第2章）との対応によって判断する。')
