H3('田園バスの見直し検討との接続')
P('**金ケ崎町都市計画マスタープラン第3章2(2)は、コミュニティバス（田園バス）を「都市計画区域外（郊外部）における交通弱者の買い物・通院・娯楽など日常生活を支えるネットワーク」と位置づけ、次のとおり検討課題を挙げている。**')
BUL('**「今後の人口減少や高齢化の進展を見据え、郊外部、地域拠点及び中心拠点との交通ネットワークのあり方は今後の重要課題です」**')
BUL('**「田園バス運行の効果を測定しながら、その見直しや、デマンド交通、タクシー利用助成や地域で担う運行など新たな仕組みの導入について、利用者の利便性、負担のあり方、効率性を考慮し、当町のまちづくりに適合する交通ネットワークのあり方検討・実施を進めます」**')
P('**「地域で担う運行」は、本計画の生活支援体制整備事業（住民主体の移送）と同じ内容である。都市計画部門と福祉部門で別々に検討するのではなく、本調査で把握した外出手段・外出を控えている割合・閉じこもり傾向のデータを、田園バスの見直し検討に提供する（第6章 基本方針2(4)）。**')
P('**なお、外出手段として路線バスを挙げた回答は5.7％である。都市計画マスタープランは路線バス（北上市・奥州市へのネットワーク）について「現在の路線の維持を図ります」としており、利用の少なさが直ちに路線の廃止につながる関係にはない。**')
