P('**あわせて、認知症基本法第17条（認知症の人の意思決定の支援及び権利利益の保護）に対応する施策としても位置づける。** 同条は、意思決定の適切な支援に関する指針の策定、分かりやすい形での情報提供の促進とともに、**「消費生活における被害を防止するための啓発」を例示している。** 認知症高齢者（自立度Ⅱ以上）は569人と見込まれ（第8章4-3）、**そのうちⅡb（家庭内でも支障があるが、誰かが注意していれば自立できる）が256人を占める。消費者被害に最も遭いやすいのはこの層である。** 消費生活相談窓口・警察・金融機関との連携により、特殊詐欺および消費者被害の防止の啓発を、認知症の観点から行う。')
