    ['**2ウ**', '**ケアプラン点検の実施に当たって、有料老人ホームやサービス付き高齢者向け住宅の入居者に係るものも含めている**', '**8**', '**《要確定12》**《要回答62》　管内に有料老人ホーム等がない場合は、**町外に入居する被保険者のサービス利用の実態について情報収集を行い、必要に応じ県・他市町村と連携して対応できる体制**でも対象となる'],
