SRC('資料：令和8年度 保険者機能強化推進交付金 評価指標（市町村分）目標Ⅱ（ⅰ）。**「対象となる」「含む」は同評価指標の留意点の記載による**')
P('**1ウ・エの16点は、本計画への記載と進捗管理の運用で取れる（第3章5・第9章2）。2ウ・エ・オの24点は、仕組みの新設を要する。**とくに**2エ・オはリハビリテーション専門職等の関与を前提とするが、本町の地域リハビリテーション活動支援事業は「実施無」であり、その理由が「リハビリテーション専門職の人手不足」である（第3章3）。**したがって**町単独で仕組みを持つのではなく、関係団体または県・近隣市町村との広域の枠組みで関与を得ることを前提とする（第7章5⑨）**《要確定12》**。**', before=6.0)
P('**福祉用具・住宅改修は、適正化の効果が最も見えやすい分野でもある。**第9期計画の推計では住宅改修費が0円と置かれていたが、実績は年11人・896千円である。**リハビリテーション専門職の関与は、交付金の得点のためだけでなく、用具の選定と改修の内容を利用者の状態に合わせるための手続でもある。**')
doc.add_page_break()
