P('**本章は本計画で新設する章である。** 国の第10期基本指針（案）は、サービス種類ごとの量の見込みについて、計画期間の各年度に加えて**令和22年度（2040年度）を含む中長期的な推計を定めること**を求めている。**第9期計画には対応する章がない。**')
P('**本計画では、令和22年度に加えて令和15年度・令和30年度の推計を示す（第2章7）。本章はその推計を、施設・人材・連携の3つの側面から施策に接続するものである。**')
