SRC('資料：被保険者数は社人研「日本の地域別将来推計人口」。**認定者数は第10期ワークシート（推計パターン「0908」）の総括表（令和8年9月28日出力）による（令和12年度804人・令和17年度831人・令和22年度890人・令和27年度910人・令和32年度894人）。令和15年度・令和30年度は前後の年度から補間した。** **要介護3以上は同ワークシートの要介護度別の内訳の合計であり、令和7年度は要介護3 127人＋要介護4 99人＋要介護5 71人＝297人、令和11年度は要介護3 121人＋要介護4 108人＋要介護5 71人＝300人である。介護保険事業状況報告 様式1による令和7年度末（令和8年3月31日）の実績は288人（要介護3 119人＋要介護4 103人＋要介護5 66人）であり、推計の基準年度とは基準が異なる（０-７）**')
P('**要介護3以上は令和7年度297人から令和11年度300人へ3人増えるにとどまる。さらに増えるのは令和12年度以降であり、令和30年度に340人となる（43人・14.5％増）。** 本表は第2章7・第8章と同じ系列（第10期ワークシート「0908」）による。**計画書全体で認定者数の系列は1つである。**')
P('**需要は単調に増えない。3つの段階に分かれる。**')
