P('**したがって、確保方策は町内一律ではない。永岡では「減る需要のもとで事業所をどう残すか」、三ケ尻では「増える需要をどう受けるか」が課題となる。残る街・南方・西部は大字西根に含まれており、行政区一覧の受領後に同様の整理を行う《要回答24》。**')
P('**なお、訪問系の供給力は職員の人数ではなく勤務時間で把握する必要がある。介護人材実態調査によれば、訪問系は77人のうち49人（63.6％）が非常勤で、職員1人あたりの週の勤務時間は29.2時間（施設・居住系35.8時間）である。また土日の身体介護は常勤職員が平日の3分の1以下（32.0分→9.5分）に減り、非常勤職員（平日17.8分・土日15.8分）が支えている（第7章5）。**')
P('**なお、地区生涯教育センターは6生活圏すべてにあり、都市計画マスタープランは「地域拠点＝生活圏の中心となるエリア」と位置づけている。訪問系サービスの拠点ではないが、通いの場・介護予防の場としては、需要が3分の2に減る永岡でも維持される見込みである。** ただし同計画書は公共施設等総合管理計画による多機能集約化・統合廃止の検討にも言及しており、**拠点の維持を前提に置けるかを町に確認する《要回答》。**')
