P('**したがって本町の確保方策は、「新設して増やす」ではなく「既存の施設・事業所の機能を高め、必要に応じて転換・多機能化できるようにしておく」ことを基本とする。** 国は、需要の減少が見込まれる地域における大規模施設の新設について、**「長期間にわたる費用の償還が必要となる大規模施設を新たに整備することには、高いリスクが伴います」「特別養護老人ホームの入所要件は要介護3以上が原則となっていることから、要介護者の減少が見込まれる地域では、今後は十分な利用者が確保できない状況も想定されます」**としている。**令和22年度以降の整備の判断は本計画期間中に行う**《要確定5》**。**')
