P('**町内施設は圏域の看取りを担う一方で、入所者の3分の1超が町外の住民である。施設の整備・維持は町単独では判断できず、県および奥州市との広域調整を要する。**')
P('**本計画における医療・介護連携の課題は、「連携そのものが弱い」ことではなく「現場で行われている連携を町が把握し記録する仕組みがない」ことである。** 第9期の成果指標6項目の実績が集まらなかったこと（第3章1）と同じ構図であり、**第6章 基本方針4(1)では、連携の実績を毎年度把握する仕組みの整備を施策の中心に置く。**')
P('**協力医療機関連携加算の算定率が12.5％（偏差値39.92）にとどまることは、令和9年3月末に義務化される協力医療機関の確保が進んでいないことを示す。確保できていない施設のリスト化を、計画期間の初年度ではなく令和8年度中に前倒しする。**')
P('**協力医療機関を確保できていない施設のリスト化を、計画期間の初年度（令和9年度）に行う。義務化の期限が令和9年3月末であり、計画期間の開始と重なる。**')
