P('**単独世帯が20年間で847世帯増加している（第2章1）。持家に一人で住み続けられなくなったときの受け皿が、施設か住まいかによって、必要となるサービスの種類が変わる。見込量の推計に直接影響する。**')
P('**既存住宅の活用の可能性　―　街地区**　金ケ崎町都市計画マスタープラン第4章2は、街地区について「平成27年度の空家等実態調査では、町内全域の空き家の約4割が当地区に集中している状況です。なお、うち利用可能な空き家は町全体の45.8％と比して当地区は52.9％と、比較的状態の良い空き家がある状況です」としている。')
P('**街地区は町内で最も空き家が多く、かつ状態も比較的良い。同地区は中心拠点（金ケ崎駅・役場・金ケ崎診療所）に隣接し、日常生活に必要な都市機能が徒歩圏にある。高齢者向け住まいの検討にあたり、新設と既存住宅の活用のいずれを取るかの判断材料になる。** ただし調査は平成27年度であり、**最新の空家等実態調査の結果を町から受領する《要回答26》。**')
P('**居住に係る施策との連携　―　法第117条第3項第8号**', before=10.0)
