P('**「生産年齢人口が令和30年度までに32.2％減る」というのは将来の話であるが、職員数の減少はすでに起きている。本計画では、人材確保を「中長期の課題」ではなく「計画期間中の制約条件」として扱う。需要側の施策をいくら設計しても、担い手がいなければ実現しない。**')
