P('**訪問系は非常勤への依存が4系統で最も大きい。事業所票では77人のうち49人（63.6％）が非常勤、職員個票では常勤47.2％・非常勤52.8％である。職員1人あたりの週の勤務時間も29.2時間と最も短い。事業所票の人数に個票の常勤・非常勤別の平均勤務時間を乗じると、訪問系の供給力は週2,132時間、施設・居住系は週5,539時間で、人数の比（1対2.0）より差が大きい（1対2.6）。**')
P('**訪問介護の給付費は令和7年度に20.0％増えている。これを支えているのは、週22.2時間しか勤務しない非常勤職員49人である。訪問系の供給力は、常勤職員の採用数ではなく、非常勤職員の人数と1人あたり勤務時間の両方で決まる。**')
