FIG('out/fig/s15_seikatsu.png', '訪問介護員の年齢別に見た提供時間の構成比', width=14.2, src='資料：上表に同じ。**生活援助の40.4％を70歳以上が担っている。70歳以上が退いたとき、まず失われるのは生活援助の供給である。**')
P('**生活援助の提供時間の71.4％を60歳以上が担い、70歳以上だけで40.4％を占める。身体介護でも60歳以上が52.4％である。70歳以上の訪問介護員は提供時間に占める身体介護の比率が38.7％と最も低く、掃除29.2％・調理配膳19.6％と生活援助が中心である。**')
P('**この2つを重ねると、70歳以上の訪問介護員が退いたとき、まず失われるのは生活援助の供給である。生活援助を地域の担い手へ移す検討は「サービスの効率化」の問題ではなく、現に生活援助を担っている職員が最も高齢であるという供給の維持の問題である（第6章 基本方針1(5)）。**')
