SRC('資料：同調査 p12。前の職場が介護事業所である職員の前職場の場所')
P('**前職が介護事業所である17人のうち41.2％は町内の別の事業所からの移動である。訪問系では75.0％（4人中3人）が町内からの移動であり、町全体の職員数は増えていない。**')
P('**一方、過去1年間に職場が変わった職員24人（同一法人・グループ内の異動を除く）の内訳は、介護事業所からの転職13人・「以前は介護以外の職場で働いていた、または働いていなかった」11人である（同調査p13）。介護以外／無業からの11人のうち8人（72.7％）が施設・居住系に入り、訪問系へは1人にとどまる。**')
P('**訪問介護には資格要件があるため、異業種からの直接参入がほとんど起きていない。介護職員就職支援助成金は「他の事業所から引き抜く」設計ではなく「異業種・無業から介護分野へ入る人を増やす」設計に重点を置き、訪問系については初任者研修の受講支援と組み合わせる。**')
H3('介護人材の必要数の推計')
P('**国の基本指針は、「二千四十年等の中長期を見据えて、第九期に必要となるサービスの種類ごとの量の見込み等を定めるとともに、それらを基にサービスを提供するために必要となる介護人材の数等を推計することが重要である」としている。**')
P('**推計の方法は、国が都道府県別に示す令和22年度（2040年度）までに必要となる介護職員数を、本町の要介護認定者数の比で割り戻すものである。**')
TBL([
    ['', '**内容**', '**値**'],
    ['**①**', '**岩手県の令和22年度の介護職員必要数**', '**《要回答60》**'],
    ['**②**', '**岩手県の要介護認定者数**', '**《要回答60》**'],
    ['**③**', '**本町の令和22年度の第1号認定者数**（第2章7）', '**893人**'],
    ['**④**', '**本町の必要数 ＝ ① × ③ ÷ ②**', '**【　】人**'],
    ['**⑤**', '**（参考）令和8年8月現在の町内の介護職員数**（介護人材実態調査。18事業所の回答による）', '**265人**'],
], widths=[1.0, 10.4, 5.4])
SRC('**①②は厚生労働省「介護保険事業計画に基づく介護職員の必要数について」の都道府県別の値による**《要回答60》**。⑤は回収18事業所（回収率69.2％）の集計であり、町内の全事業所を網羅したものではない**')
P('**この方法は、現状の配置職員数を基礎に要介護者の伸びを乗じるものであり、本町のサービス基盤整備の方針を反映していない機械的な推計である。** 国の手引きもその旨を明記している。**したがって④は「町の方針を織り込まない場合の目安」であり、本計画の確保方策の目標値ではない。**')
P('**本計画で実際に用いるのは、介護人材実態調査による実測である（前項まで）。職員数は昨年比97.1％（採用41人・離職49人）であり、必要数が増えるか否か以前に、現に減っている。** 7-2の確保方策（サービス種類ごとの供給の上限）は、この実測に基づいて置いている。')
H3('確保の方策')
TBL([
    ['**方策**', '**内容**'],
    ['**①介護職員初任者研修の受講支援**', '**訪問介護の担い手は資格取得を経なければ増やせない。** 受講費用の助成・受講中の生活支援を、異業種・無業からの参入者を主たる対象として設計する。**訪問系の職員の39.6％が初任者研修修了者であり、入口として現に機能している**'],
    ['**②非常勤職員を含む処遇改善・働き方の支援**', '**訪問系は63.6％が非常勤で、土日の在宅支援を支えている。** 常勤化を促すだけでなく、非常勤のまま働き続けられる条件（シフト・移動時間の扱い・直行直帰）の整備を事業所と協議する'],
    ['**③異業種・無業からの参入支援**', '**過去1年間に異業種・無業から11人が参入している（うち8人が施設・居住系、訪問系は1人）。** 介護職員就職支援助成金の対象・要件をこの層に合わせる。**第9期は令和7年度までに121人・12,460,000円（1人あたり102,975円）を交付し、令和8年度末には目標134人を上回る見込みであるが、同じ期間に町内の介護職員数は昨年比97.1％と減っている。交付人数だけでなく定着率を併せて把握する**'],
    ['**④通所系の資格取得支援と認知症介護の研修**', '**通所系は「いずれも該当しない」が19.6％。** 認知症介護基礎研修の受講状況を確認し《要回答27》、初任者研修・実務者研修への接続を図る。**認知症基本法第18条第3項は「認知症の人の保健、医療又は福祉に関する専門的知識及び技術を有する人材の確保、養成及び資質の向上」を求めており、認知症介護基礎研修（令和6年度から全事業所で義務化）・実践者研修・実践リーダー研修の受講は本計画における人材施策の一部である。認知症高齢者（自立度Ⅱ以上）は認定者の69.3％を占めており（第2章3）、認知症介護はすべてのサービスに共通する基礎である**'],
    ['**⑤介護支援専門員の確保**', '**居宅介護支援事業所は6→5に減り、介護支援専門員は14人→13人→12人と減少している一方、居宅介護支援等の計画比は119.3％である。** ケアマネジメントの需給が最も逼迫している'],
    ['**⑥介護人材確保プラットフォームへの参画**', '**国の第10期基本指針（案）で明記された事項。** 県の取組と連携する'],
    ['**⑦テクノロジーの活用・生産性向上**', '**《要回答3》事業所ヒアリングにより、導入状況と支援ニーズを把握する**'],
    ['**⑧事業者の経営改善支援**', '**国の第10期基本指針（案）で新たに明記された事項。** 町内の事業所数は7年間不変であり、1事業所の撤退が供給に直接響く'],
    ['**⑨リハビリテーション専門職等の関与の枠組み**', '**町単独では確保できないため、関係団体または県・近隣市町村による広域団体との連携により関与を得る枠組みを検討する。** 用途は3つある。**①介護予防の場・地域ケア会議への派遣（基本方針1(4)）　②福祉用具の貸与後の点検、福祉用具購入費・住宅改修費の妥当性の検討（基本方針5(4)）**《要確定12》**　③難聴の早期介入（基本方針3(3)）**《要確定11》**。**いずれも**個別に人を確保するのではなく、1つの協議の場に集約する**'],
], widths=[4.6, 12.3])
P('**なお、本調査は毎年度同じ様式で実施できる。「町内の介護職員数（前年度比）」を成果指標の候補とする（第9章3）。第9期で6指標の実績が集まらなかった原因は集計の仕組みがなかったことであり、本調査はその仕組みそのものである。**')
