P('**既に取得した地域差指数（第3章1）は全国を1.00とする指数であり、同じ考え方に立つが、指標が「1人あたり給付月額」であって「提供量」ではない。両者は別のものであり、置き換えて用いることはできない。**')
P('**また、介護SCRと「介護サービス自給率」も別の指標である。** 自給率は、市町村内に存在する事業所における給付月額を当該市町村における給付月額で除した割合であり、**町民が町外の事業所を使うと下がるが、町外の住民が町内の事業所を使っても変わらない。** 町内施設の入所者の36.1％が町外の住民であること（第7章3）は、この指標には現れない。**計画書では3つの指標の定義を併記する。**')
