H1('第８章　介護保険事業費と介護保険料の見込み')
P('**本章に掲げる数値は、別途お示しする算定シート（「第10期　見込量・給付費・保険料の算定」）と1円まで一致する。** 算定は次の順序による。**①令和7年度実績を基準年度とする　→　②令和8年度を置き直す　→　③令和9〜11年度に伸びを乗せる　→　④施策と供給の制約を反映する　→　⑤地域支援事業費を積む　→　⑥保険料まで通す　→　⑦感応度で論点を分ける。**')
P('**受領した第10期ワークシート（推計パターン「0908」）の令和9〜11年度をそのまま用いていない。基準年度の置き方が異なるためである。** 同ワークシートの令和8年度は、8サービスが0、2サービスが約3倍、4サービスが半減以下となっており、令和7年度実績との連続性を欠く。**その理由は8-1で確かめたとおり、令和8年度が年度の値ではなく1か月分の値だからである。** 令和9〜11年度はその令和8年度を起点としているため、単月のぶれがそのまま3年間に及ぶ。**本計画では令和8年度を令和7年度実績から置き直したうえで、ワークシートの伸びを乗せる。**')
P('**見込量は需要で置くことを原則とする。** 町外事業所の利用も保険給付の対象であるため、町内の供給力の不足を理由に見込量を減らさない。**ただし地域密着型サービス（小規模多機能型居宅介護・認知症対応型共同生活介護・地域密着型介護老人福祉施設・認知症対応型通所介護・定期巡回随時対応型）は、町が指定した事業所のみが提供するため、供給力が見込量の上限になる。** この区別が、第7章2の確保方策と本章の見込量とをつなぐ基準である。')
P('**なお、確認事項《要回答35〜37・46》の回答により、本章の数値は変わる。** 変わる範囲は8-7の感応度に示した。**回答を待つあいだ算定を止めない代わりに、どの回答がどの数値を何円動かすかを明示する。**')
