P('**施設・居住系は横ばい、居宅・地域密着型は令和7年度から4.9％増える。** 要介護3以上が295〜300人でほぼ横ばいであること（8-2）と、居宅サービス給付費が令和7年度に＋10.6％と伸びていること（第2章5）の双方に整合する。**「施設から在宅へ」ではなく、「施設は動かず、在宅が伸びる」姿である。**')
P('**介護予防サービスが令和7年度から5.3％増える一方、要支援1・2の認定者数は175〜177人でほぼ横ばいである。** 増加は2つのサービスに集中している。**介護予防福祉用具貸与が54.5人／月→59.9人／月（＋5.4人）、介護予防支援が66.5人／月→73.3人／月（＋6.8人）である。** 介護予防支援は要支援者のケアマネジメントであり、要支援者に占める割合が37.8％から41.4％へ上がることを意味する。**この上昇の根拠は第10期ワークシートから読み取れないため、確認事項に加える**《要回答35》**。**')
P('**要支援者への関わりを増やすこと自体は、第4章2の生活機能リスク（社会的役割の低下55.6％・認知機能の低下44.1％・うつ傾向42.8％）に照らせば抑えるべきものではない。ただし、掃除・調理配膳が提供時間の6割を占める実態（第6章 基本方針1(5)）を踏まえ、内容の点検を地域ケア個別会議で行う。**')
