SRC('単位：千円／年。**その他給付費は特定入所者介護サービス費等・高額介護サービス費等・高額医療合算介護サービス費等・算定対象審査支払手数料の合計であり、第10期ワークシートが算定した額を用いた。** 第9期計画値の対総給付費比は7.6227％であったが、**介護保険事業状況報告による実績比は平成29年度7.549％・令和2年度8.113％・令和5年度6.879％と低下しており、主因は特定入所者介護サービス費等の減少（平成29年度62,957千円→令和5年度51,942千円・▲17.5％）である。7.6227％を第10期に当てはめるのは過大である**《要回答41》')
P('**単位は「千円／年」で統一する。** 第9期計画書 p73 は介護給付費の推計表の単位を「人／月」と表記していたが、これは誤植であり、表の値は千円／年であった。**また住宅改修費が3か年とも0円と置かれていたが、実績は令和5年度で11人・896千円ある。本計画では実績のあるサービスを0で置かない。**')
P('**この原則は第10期ワークシートにも当てはめた。** 同ワークシートは住宅改修費・特定福祉用具購入費・特定施設入居者生活介護・認知症対応型通所介護・介護予防住宅改修・特定介護予防福祉用具購入費・介護予防居宅療養管理指導・介護予防特定施設入居者生活介護の**8サービスを令和8年度以降すべて0としているが、いずれも令和7年度に実績がある。本計画では令和7年度実績から復元した（3か年で19,248千円・月額26円）。**')
