P('**第6章で新設する7施策のうち、(1)(2) 通いの場の拡充、(1)(5) 訪問型サービスAの拡充、(2)(4) 通いの場への送迎の拡大、(4)(3) 多様な生活支援サービス、(4)(4) 家族介護者への支援　の5つは、いずれも地域支援事業費で担うものである。** 第4章8が示す住民の要望の第1位（予防対策45.8％）と第2位（移動手段の確保45.4％）も同じである。**しかし総合事業費の上限の伸びは3年で4.13％しかない。新設する施策の財源を上限の伸びだけで賄うことはできず、既存事業費の組替えまたは一般財源によることになる。**')
P('**この点は、施策を並べる前に第2回策定委員会でご議論いただく必要がある。** 財源の裏づけのない施策を計画に掲げると、第9期の成果指標が最終年度まで実績を確認できなかったこと（第3章1）と同じ結果になる。')
