P('**認知症高齢者（Ⅱ以上）569人に対し、グループホームの定員は27人で4.7％にあたる。残る542人は在宅または他のサービスで暮らしている。** 定員を増やすかどうかの判断には、**①待機者数　②町外のグループホームを利用している方の人数　③既存3施設の増床の可否**の3つが必要であるが、いずれも受領していない《要回答49》。**第2回策定委員会に定員の変更を諮るには、これらが揃っていることが前提となる。**')
P('**ただし、本町の数字が示す方向は増床ではない。** 自立度Ⅱ以上の増加93人はすべてⅡbで生じ、施設の主たる対象であるⅢ以上は9人（2.6％）しか増えていない（第2章3）。**必要なのは居室ではなく、家庭内で注意を向ける人と、出かけられる場である。認知症基本法第15条（見守り体制の整備）・第16条（社会参加の機会の確保）・第19条第2項（交流活動への支援）が求めているのはこの3つであり、いずれも地域支援事業と住民の関わりで担うものである。**')
