SRC('**目標値は第9章3の3原則による。現状値が把握できている指標には【案】を置き、現状値が把握できていない2指標（初期集中支援チームの対象者数・チームオレンジ）には目標値を置かず「—」とした**《要回答49》**。令和9年度からの記録様式の整備は第9章5に位置づけている。** 認知症サポーターは累計ではなく年間の養成数で置いた。累計は町の人口の26.2％に達しており、量的な拡大の余地が小さいためである。**認知症の日（9月21日）・認知症月間（9月1〜30日）は認知症基本法第9条第3項に基づくもので、本町に現在の取組がないため令和9年度から年1回以上とした**')
