P('**個別に検討した項目の小計は＋22,010千円（＋28円）である。すなわち、施策と供給の制約を個別に検討した結果は、増やす方向と減らす方向がほぼ相殺する。** 保険料を動かしているのは、残る全サービスに及ぶ令和8年度の置き直し（▲192,018千円・▲243円）である。')
P('**この分解が示すことは2つある。第一に、施策の反映は保険料の水準を動かす手段ではない。第二に、それでもサービス別の内訳は大きく動き、それが第7章2の確保方策の対象を決める。** 保険料の議論と、提供体制の議論は、分けて行う必要がある。')
H2('８-８　感応度　―　第2回・第3回策定委員会でご議論いただく事項')
P('**基準額5,322円（準備基金取崩前）・4,782円（9,000万円取崩後）を基準とする。**')
TBL([
    ['**論点**', '**月額**', '**判断の材料**'],
    ['**令和8年度をワークシートの値に戻す**', '**＋216円**', '**ワークシートの令和8年度は1か月分の値である（8-1）。在宅21サービスの利用者数がすべて整数であり、令和6・7年度が12か月平均であるのと性質が異なる。8サービスが0、2サービスが約3倍、4サービスが半減以下となるのはこのためである。令和8年度の月報（202605以降）を受領できれば、この論点は消える**《要回答35》'],
    ['**準備基金を9,000万円取り崩す**', '**▲540円**', '**第9期は9,000万円の取崩しにより5,450円を4,900円に下げた。町のご判断**《要確定》'],
    ['**第1号被保険者負担割合が1ポイント上がる（23％→24％）**', '**＋232円**', '**3年の計画期間ごとに政令で定められる。第10期分は未確認**《要回答43》'],
    ['**令和8年度の認定者数が令和7年度と同水準（813人）であった場合**', '**＋45円**', '**一律の伸び▲2.214％は、ワークシートの令和8年度795人と令和7年度813人の比による。795人も1時点の値であり、18人の減が実際のものか一時的なものかは確認を要する。** 中間の804人とした場合は＋23円**《要回答46》**'],
    ['**後期高齢者加入割合補正係数が第9期と同じ水準であった場合**', '**＋251円**', '**同係数の算出に用いる全国値は、第10期の係数シートでは「（仮置値）」とされ、第9期の令和6〜8年度の値がそのまま入っている。確定すれば動く**《要回答45》'],
    ['**地域密着型特別養護老人ホームの稼働率が100％に回復する**', '**＋78円**', '**友愛の家（定員20人）で介護職員が常勤換算13.4人→11.0人に減った年に稼働率が下がった。人材確保の成否に直結する**《要回答37》'],
    ['**令和9年度介護報酬改定率が＋1.59％（第9期と同率）となる**', '**＋76円**', '**例年12月下旬の予算大臣折衝で決定する。第3回策定委員会（12月16日）には間に合わない可能性が高い**'],
    ['**グループホームをワークシートどおりに置く**', '**▲58円**', '**ワークシートは令和9年度のみ63,370千円に下げている。定員の変更予定の有無で決まる**《要回答36》'],
    ['**介護予防通所リハをワークシートどおり2.7倍とする**', '**＋45円**', '**2.7倍の根拠が確認できていない**《要回答35》'],
    ['**訪問介護をワークシートどおりとする**', '**▲20円**', '**需要側は自然体、供給側は自給率55.93％。町外事業所への依存が続く前提でよいか**'],
    ['**地域支援事業費を第9期と同額に据え置く**', '**▲5円**', '**上限まで積んでも月額5円しか動かない。新設施策の財源は既存事業費の組替えによるほかない**'],
], widths=[7.0, 1.8, 7.0])
FIG('out/fig/s17_kanno.png', '保険料の水準を動かす論点　―　基準額（月額）に与える影響', width=15.0, src='資料：上表に同じ。**町のご判断によるものは2つ、国が決めるものは3つ、事実の確認によるものは6つである。**')
P('**保険料の水準を動かすのは、①準備基金の取崩し（540円）　②後期高齢者加入割合補正係数（251円）　③第1号被保険者負担割合（1ポイント232円）　④令和8年度の基準の置き方（216円）　⑤令和8年度の認定者数（45円）の4つと1つである。** ④⑤は事実の確認により決まるもの、①は町のご判断、②③は国が決めるものである。**性質が異なるため、委員会には分けてお示しする。**')
P('**従前、認定者数の系列の選択として月額129円と見ていた論点は、8-1の検証により解消した。振れ幅は⑤の45円に縮んでいる。**')
P('**このうち②③は、いずれも第10期の係数シートが「（仮置値）」「未確認」としているものに由来する。合計で483円、基準額の9.1％にあたる。第3回策定委員会（12月16日）の時点でも確定していない可能性が高く、暫定値と幅で示すほかない（8-1）。**')
doc.add_page_break()
H1('第９章　計画の推進と進捗管理')
P('**本章は第9期計画から最も大きく変える章である。** 第9期の第7章は1頁・2項目（推進体制と進捗管理）で構成され、**誰が・いつ・どの資料で・何を基準に評価するかの記載がなかった。第9期の成果指標8項目のうち6項目の実績が最終年度まで確認できず、1項目は目標と実績が別のものを指していたことは、この記載の不足と無関係ではない。**')
H2('９-１　計画の推進体制')
P('本計画の推進にあたっては、主管課（保健福祉センター）および庁内関係課による検討に加え、金ケ崎町介護保険運営協議会において進捗状況を議論し、地域における課題や資源を共有する。')
P('**認知症施策推進計画の部分については、認知症の人およびその家族等の意見を聴く機会を進捗管理の場に位置づける（認知症基本法第13条第3項において準用する同法第12条第7項）。具体の手順は9-4に定める。**')
P('**認知症施策は、保健・医療・福祉のほか、地域づくり・雇用・交通・産業など複数の分野にまたがる。**国の認知症施策推進基本計画は、計画の策定にあたって「地方公共団体内における保健・医療・福祉・教育・地域づくり・雇用・交通・産業等の担当部局同士が緊密に連携し、それぞれが責任を持って取り組む」ことを求めている。**本計画では、新たな会議体を設けず、既存の庁内連携の場（第7章5）に認知症施策を議題として加える。**移動支援は都市計画部門（第4章4）、住まいは住宅部門（基本方針2(2)）、事業者との連携は商工部門（基本方針3(0)キ）と、それぞれ既に接点がある。**接点があるものを、同じ場で扱う。**')
H2('９-２　進捗管理の方法')
TBL([
    ['**項目**', '**内容**'],
    ['**評価の実施主体**', '**保健福祉センター（主管）。指標ごとの集計担当課は9-3の一覧表に明記する**'],
    ['**評価の時期**', '**毎年度6月末までに前年度の実績を集計し、8月の介護保険運営協議会に報告する**《要確定》'],
    ['**評価の様式**', '**9-3の成果指標一覧表を毎年度更新する。様式は本計画の別表6として固定する**'],
    ['**評価の基準**', '**現状値（令和8年度）と目標値（令和11年度）を結ぶ線に対する進捗で判定する**'],
    ['**評価の根拠となる事業**', '**一般介護予防事業評価事業（基本方針1(4)）。この事業がないと実績が集まらない**'],
    ['**公表の方法**', '**町ホームページおよび広報かねがさきにより公表する**'],
    ['**あわせて報告する事項**', '**介護給付適正化（基本方針5(4)）・在宅医療・在宅介護連携（基本方針4(1)）・認知症総合支援（基本方針3）についても、同じ様式で毎年度の課題分析・改善見直しを行い、成果を公表する。** 交付金の評価指標が、いずれもこれを求めているためである（第3章5）'],
    ['**交付金の評価結果の公表**', '**保険者機能強化推進交付金および介護保険保険者努力支援交付金について、直近年度の評価結果を、評価項目（枝番）ごとの得点獲得状況まで含めて公表する。** 別冊「交付金の体系と本町の位置」がそのまま公表資料になる。**評価結果を庁内で共有する場と、介護保険運営協議会への報告をあわせて行う（第3章5）**'],
    ['**難聴の取組の評価**', '**基本方針3(3)の難聴高齢者の早期発見・早期介入について、講話等の実施回数・参加実人数、簡易な聴こえの確認の人数、受診を勧めた人数、そのうち受診につながった人数を毎年度把握し、同じ様式で報告する（9-3）。** 交付金の評価指標が求める「早期発見・早期介入の取組の実施」を裏づける記録でもある'],
    ['**未把握時の措置**', '**令和8年度の現状値が把握できない指標については、目標値を設定せず、令和9年度からの記録様式の整備を計画に位置づける。把握できない指標に目標値だけを置くことは、第9期と同じ結果を招く**'],
    ['**次期計画に向けた調査**', '**計画2年目（令和10年度）に、介護予防・日常生活圏域ニーズ調査・在宅介護実態調査・介護人材実態調査に加え、在宅生活改善調査および居所変更実態調査を実施する。** 後の2つは本計画では未実施であり、**「真に入所が必要と判断される被保険者」の把握（第7章2）と施設・居住系の確保方策の根拠となる。いずれも予算を要さず電子メールで実施でき、自動集計により報告書まで作成できる。** 計画1年目（令和9年度）に実施の要否と設問を庁内で検討し、次年度の予算・体制を整える'],
], widths=[4.0, 12.9])
H2('９-３　成果指標')
P('**指標は3階層に分ける。この3階層は交付金の3指標群（成果指標群／（ⅱ）活動指標群／（ⅰ）体制・取組指標群）と同じ構造であり、計画の進捗管理と交付金の自己評価を1つの表で行える（第3章5）。**')
H3('目標値の設定の考え方')
P('**第9期は、8指標のうち6指標の実績が最終年度まで確認できず、1指標（シルバー人材センターの受託件数）は減少している指標に増加目標を置いて未達となった（第3章1）。同じことを繰り返さないため、目標値の置き方に3つの原則を立てる。**')
TBL([
    ['', '**原則**', '**第9期で何が起きたか**'],
    ['**①**', '**現状値が把握できていない指標には、目標値を置かない**', '**8指標のうち6指標で現状値・実績の把握の仕組みがなく、目標値だけが置かれていた**'],
    ['**②**', '**目標値は、ア　過去の実績の趨勢　イ　全国・県の水準　ウ　事業の投入量　のいずれかで説明できるものに限る**', '**シルバー人材センターの受託件数は、第8期に29団体の目標に対し21団体であった老人クラブと同様、根拠のない上積みであった。750件→950件（＋26.7％）に対し実績726件（目標比76.4％）**'],
    ['**③**', '**「維持」も目標である。減っている指標に増加目標を置かない**', '**同上。減少局面にある指標に26.7％の増加を求めたことが、未達の直接の原因である**'],
], widths=[1.0, 7.4, 8.0])
P('**以下の表の目標値は当方の案であり、町のご判断による**《要確定10》**。** 各案の根拠は表の後に掲げる。**現状値が把握できていない8項目（在宅生活の継続意向・老人クラブ・地域ケア会議・医療介護関係者の会議・チームオレンジ・初期集中支援チームの対象者数・家族介護者の会・受診につながった者の割合）には目標値を置かず、令和9年度からの記録様式の整備を計画に位置づける（9-5）。**')
P('**指標は43項目である**（成果10・活動23・体制10）。**うち7項目は2つの数値を併せて把握するため、数値の数では50となる**（全体の重度化率と軽度化率／老人クラブの団体数と会員数／地域ケア会議の開催回数と検討件数／介護職員就職支援助成金の交付人数と定着率／家族介護者の会の開催回数と参加実人数／聴こえに関する講話等の実施回数と参加実人数／ピアサポート活動の実施回数と参加実人数）。**第9期からの継続が8項目、新設が33項目である。第9期の8指標はすべて継承したうえで、定義を改めたものがある。新設33項目のうち4項目は認知症基本法に由来し**（チームオレンジ・初期集中支援チームの対象者数・認知症の日および認知症月間の取組・認知症の人およびご家族から意見を聴いた回数）、**4項目は難聴高齢者の早期発見・早期介入に係るものである（基本方針3(3)）。**')
