TBL([
    ['**№**', '**事項**', '**案**', '**影響**'],
    ['**1**', '**人口推計の基礎をどれにするか。** 見える化システムの将来推計機能は、①「日本の地域別将来推計人口」　②同を補正したデータ（性年齢階級別／前期・後期高齢者別）　③独自データ　の3択を用意している', '**①「日本の地域別将来推計人口」による。** 第9期のコーホート変化率法（③に相当）は用いない', '**令和22年度の高齢者人口が443人（10.2％）増える。施設整備の判断に直結する。最優先。** なお社人研の令和7年10月1日の第1号被保険者4,766人に対し実績は4,681人（令和8年3月31日）で85人の差があり、②の補正を選ぶ余地がある。**推計機能から「推計人口と第1号被保険者数との比較結果」をダウンロードして差を確認したうえで判断する**'],
    ['**2**', '**令和30年度の保険料を幅で示すことの可否**', '**幅で示す。** 単一値は令和15年度のみ', '**幅3,980円。単一値を出すと確度を偽ることになる**'],
    ['**3**', '**第1号被保険者負担割合の扱い**', '**中位は国の推計ツールの仮定（→28％）を織り込み、23％固定の値を必ず併記する**', '**令和30年度で1,249円（20.0％）。町の事情ではないことを分けて示す。第10期分の政令は未確認**《要回答43》'],
    ['**4**', '**1人あたり給付費の高位を年率＋0.5％としてよいか**', '**＋0.5％とする**', '**幅の大きさを規定する**'],
    ['**5**', '**施設・居住系サービスの整備方針**（新設によるか、既存施設の有効活用・用途転換によるか）', '**既存施設の有効活用・用途転換を先に検討する**', '**要介護3以上が令和30年度までに43人増える。第7章2**'],
    ['**6**', '**特例介護サービス等の導入検討手順を本計画に記載するか**', '**手順のみ記載する**', '**第7章6。地域の分類（一般市等）の分析は事務連絡Vol.1485により必須**'],
    ['**7**', '**外国人介護人材の受入環境整備を本計画に記載するか**', '**県の取組状況を踏まえて記載する**', '**第7章5。事務連絡Vol.1485が人材確保の4本柱の一つとして挙げている。第9期・本素案とも記載がない**'],
    ['**8**', '**認知症の人およびご家族から意見を聴く機会を設けるか**（策定時および毎年度の評価時）', '**Ａ　実施する**（既存の場で1回・30分〜1時間。新たな予算措置は不要）。**Ｂ　実施しない**場合の記載ぶりは第6章 基本方針3(0)オに併記した', '**認知症基本法第13条第3項において準用する第12条第3項・第7項による。第9期にこの手続はない。努力義務であり罰則はない。**交付金では、介護保険保険者努力支援交付金 目標Ⅱ（ⅰ）1カ「認知症の人及び家族等の意見を踏まえた市町村認知症施策推進計画の策定に着手している」（配点5点・全国平均2.14点・本町0点）が該当し、「意見を踏まえた」ことが条件であるため、Ａを採ることがこの5点の条件そのものになる（第3章5）。**ただしＢを採る場合、①手続を経ていないこと②第4章6が本人の意見ではないこと③次年度以降に位置づけること　を計画書に記載せざるを得ない。第2回策定委員会（令和8年11月11日）でご判断いただく。第6章 基本方針3(0)オ・第9章4**'],
    ['**9**', '**認知症基本法第7条にいう事業者（公共交通事業者等・金融機関・小売業者）との連携の範囲**', '**サポーター養成講座の実施とSOSネットワークへの参加の働きかけから始める**', '**第6章 基本方針3(0)キ。介護保険の枠外であり、庁内の関係部署との調整を要する**'],
    ['**10**', '**成果指標の目標値**（43項目のうち、目標値を置いた26項目）', '**9-3に案を掲げた。3つの原則（現状値が把握できていない指標には目標値を置かない／趨勢・全国水準・事業の投入量のいずれかで説明できるものに限る／「維持」も目標である）による**', '**第9章3。第9期は8指標のうち6指標の実績が最終年度まで確認できず、1指標は減少している指標に増加目標を置いて未達となった。目標値の置き方そのものが第9期の課題である**'],
    ['**11**', '**難聴高齢者の早期発見・早期介入について、ウ（早期介入）・エ（フォローアップ）を計画に記載するか**（交付金 支援 目標Ⅱ（ⅰ）3ウ・エ　各5点）', '**Ａ　「検討する」として記載する**（基本方針3(3)・1(4)、9-5の記録様式の整備まで。実施は約束しない）。**Ｂ　記載しない**', '**第6章 基本方針3(3)・1(4)、第9章5。ア（普及啓発）・イ（早期発見）の10点は実施を前提に目標に置いた。ウ・エは岩手県内33保険者で取得0、全国平均もウ0.73点・エ0.24点であり、言語聴覚士の確保と記録の仕組みを前提とする。Ａを採る場合も本計画期間中の実施は約束しない**'],
    ['**12**', '**介護給付適正化において、リハビリテーション専門職等が関与する仕組みを設けるか**（交付金 推進 目標Ⅱ（ⅰ）2ウ・エ・オ　各8点・計24点）。**①福祉用具の貸与後の点検　②福祉用具購入費・住宅改修費の申請内容の妥当性の検討　③ケアプラン点検に有料老人ホーム・サービス付き高齢者向け住宅の入居者を含めること**', '**Ａ　仕組みを設け、計画に記載する**（町単独ではなく、関係団体または県・近隣市町村による広域団体との連携により関与を得る枠組みによる。第7章5⑨）。**Ｂ　記載しない**', '**第6章 基本方針5(4)・第7章5。**介護給付適正化は法第117条第3項の記載事項であり、**交付金 推進 目標Ⅱ（ⅰ）は配点68点に対し本町28点で、全国平均50.5点を22.5点下回る最大の未得点分野である。**同じ目標の1ウ・エ（16点）は本計画への記載と進捗管理の運用で取れるが、この24点は仕組みの新設を要する。**評価指標の留意点は、関係団体や県・近隣市町村による広域団体等と連携して関与する仕組みでも対象とし、住宅改修費については建築専門職・福祉住環境コーディネーター検定二級以上を含むとしている。**本町の地域リハビリテーション活動支援事業は「実施無」であり、その理由が「リハビリテーション専門職の人手不足」である'],
], widths=[0.8, 4.6, 5.0, 6.5])
